            else:
                thrust = 0.0

        # Check if near ground
        if y <= ground_y + 0.02:
            # Check if x is within platform's valid area
            platform_valid_start = platform_center - 2.0
            platform_valid_end = platform_center + 2.0
            if (x - half_width < platform_valid_start) or (x + half_width > platform_valid_end):
                # Adjust torque to tilt the lander and apply thrust
                if distance_to_platform > 0:
                    desired_angle = math.radians(10.0)
                    if angle < desired_angle:
                        torque = 120.0
                    else:
                        torque = 0.0
                else:
                    desired_angle = -math.radians(10.0)
                    if angle > desired_angle:
                        torque = -120.0
                    else:
                        torque = 0.0

                # Adjust thrust to move towards platform
                thrust = 400.0

    # Apply thrust and torque
    sandbox.apply_thrust(thrust, torque)

    # Check fuel
    if fuel < 450.0:
        # Mission fails due to insufficient fuel
        pass
